import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-ai-system-design-l4-001', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Caching', question: 'What is semantic caching for ML inference and how does it reduce costs?', options: ['Semantic caching is identical to Redis key-value caching', 'Semantic caching embeds requests and uses ANN search to find similar cached requests, returning cached responses for semantically equivalent queries. This handles paraphrases that exact-match caching misses, reducing LLM API costs by 30-60% for applications with repetitive query patterns, with a tunable similarity threshold trading hit rate for correctness', 'Semantic caching only works for image inputs', 'Semantic caching eliminates the need for model serving'], correctAnswer: 1, explanation: 'Unlike exact-match caching (hash of prompt → response), semantic caching embeds queries and searches cached embeddings by similarity. "What is ML?" ≈ "Define machine learning" would be a cache hit. Challenges: threshold tuning (too low → wrong answers from cache), embedding latency (~5ms per query), and cache invalidation for time-sensitive queries. GPTCache and LangChain implement this pattern.', tags: ['caching', 'semantic-cache', 'cost-optimization', 'embeddings'] },
  { id: 'ai-engineer-ai-system-design-l4-002', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Load Balancing', question: 'How should ML inference traffic be load-balanced differently from standard web traffic?', options: ['ML inference requires GPU-aware load balancing: route requests based on available GPU memory for KV cache, group similar-length requests for efficient batching, account for variable inference latency, and implement request queuing to maximize GPU utilization. Least-outstanding-requests routing outperforms round-robin because inference latency varies significantly per request', 'Standard round-robin load balancing is optimal for ML', 'Load balancing is unnecessary for GPU-based inference', 'ML inference has uniform latency so any load balancer works'], correctAnswer: 0, explanation: 'Standard web requests take ~similar time (10-50ms). ML inference varies widely: a 10-token generation takes 50ms, a 1000-token generation takes 5000ms. Round-robin assigns the next request to the next server regardless of current load, causing some GPUs to be idle while others are overloaded. Least-outstanding-requests routes to the GPU with the fewest pending requests, naturally balancing variable-length workloads.', tags: ['load-balancing', 'gpu-aware', 'inference', 'scheduling'] },
  { id: 'ai-engineer-ai-system-design-l4-003', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Multi-Tenant', question: 'How can LoRA adapters enable cost-effective multi-tenant ML platforms?', options: ['LoRA adapters allow per-tenant customization on a shared base model: one base model loaded on GPU with multiple small LoRA adapters swapped per request. This reduces GPU memory from N×model_size to 1×model_size + N×adapter_size (adapters are <1% of base model), enabling hundreds of tenants on a single GPU cluster while each gets a customized model experience', 'Multi-tenant platforms require no model customization', 'Each tenant requires a separate GPU with a dedicated model', 'LoRA adapters cannot be swapped at inference time'], correctAnswer: 0, explanation: 'S-LoRA and Punica enable efficient multi-LoRA serving: the base model weights stay in GPU memory while a library of LoRA adapters (each ~10-50MB for a 7B model vs 14GB base) are loaded/unloaded per request. A 7B model with 100 LoRA adapters: 14GB + 100×50MB = 19GB (fits one GPU) vs 100×14GB = 1.4TB (100 GPUs) for separate models. Custom batching groups requests by adapter for efficient processing.', tags: ['multi-tenant', 'lora', 'cost-efficiency', 'adapter-serving'] },
  { id: 'ai-engineer-ai-system-design-l4-004', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Latency', question: 'What is the end-to-end latency breakdown for a typical LLM inference request?', options: ['Typical breakdown: network (5-20ms) + input processing/tokenization (1-5ms) + queue wait (0-500ms) + prefill/TTFT (50-500ms depending on prompt length) + decode (10-50ms per token × num_tokens). Key optimizations: prefix caching (skip redundant prefill), speculative decoding (2-3x decode speedup), quantization (faster per-step compute), continuous batching (reduce queue time), and streaming responses (user sees tokens immediately, reducing perceived latency)', 'Network latency dominates all LLM requests', 'Latency optimization is unnecessary for batch inference', 'All latency comes from the decode phase'], correctAnswer: 0, explanation: 'For a typical ChatGPT-like request (1000 token prompt, 200 token response): network 10ms + tokenization 2ms + queue 50ms + prefill 200ms + decode 200×25ms = 5000ms. Total ~5.3s. TTFT (time-to-first-token) = 262ms. Optimizations: prefix caching saves 50-90% of prefill for shared system prompts. Speculative decoding generates 2-3 tokens per step. Quantization (INT4) reduces decode per-step by 2x. These compound: optimized TTFT ~50ms, total ~2s.', tags: ['latency', 'ttft', 'optimization', 'inference-pipeline'] },
  { id: 'ai-engineer-ai-system-design-l4-005', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Feature Store', question: 'What is the point-in-time correctness problem in feature stores for ML training?', options: ['Feature stores automatically prevent all forms of data leakage', 'Point-in-time correctness reduces model accuracy', 'Point-in-time correctness ensures that training examples only use features as they existed at prediction time, not future values. Without it, a model trained to predict next-day stock price might use today\'s closing price (future data) as a feature, creating data leakage that inflates training metrics but fails in production. Feature stores implement temporal joins that look up feature values at each example\'s timestamp', 'Point-in-time correctness is only relevant for real-time features'], correctAnswer: 2, explanation: 'Example: predicting fraud at time T. Feature "average_transaction_amount_30d" should be computed over [T-30d, T], not [T-30d, T+1d]. Without temporal correctness, the feature includes transactions that occurred after the prediction time, leaking the label. Feature stores like Feast and Tecton implement as_of timestamp joins: for each training example at time T, retrieve feature values as they were at time T. This is trivially correct for real-time serving (features are always "current") but requires careful implementation for batch training data generation.', tags: ['feature-store', 'point-in-time', 'data-leakage', 'temporal-joins'] },
  { id: 'ai-engineer-ai-system-design-l4-006', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Recommendation', question: 'What is the retrieval-ranking-reranking funnel architecture for recommendations at scale?', options: ['The funnel: (1) Retrieval: two-tower model generates user/item embeddings, ANN search finds top-1000 candidates from millions in <10ms. (2) Ranking: feature-rich model (cross-features, contextual signals) scores 1000 candidates in ~50ms. (3) Re-ranking: applies business rules, diversity, freshness constraints to top-100. Each stage trades precision for speed, with the most expensive models only processing the smallest candidate sets', 'A single model should score all items', 'All items should be scored by the ranking model', 'Retrieval stage does not need ML models'], correctAnswer: 0, explanation: 'For 100M items with 100ms latency SLA: scoring all items with the full ranking model (1ms/item) = 100,000s. The funnel approach: retrieval (ANN search, 5ms for top-1000) → ranking (100μs/item × 1000 = 100ms) → re-ranking (rules on top-100, 5ms). Total: ~110ms. Each stage is a different model: retrieval is a simple dot-product, ranking uses complex features (user history × item features × context), re-ranking enforces business constraints (diversity, freshness, ad inventory).', tags: ['recommendation', 'funnel', 'two-tower', 'ranking'] },
  { id: 'ai-engineer-ai-system-design-l4-007', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Streaming', question: 'When should ML predictions use streaming (Kafka) versus synchronous (REST) architecture?', options: ['Synchronous REST is always faster than streaming', 'Streaming ML is preferred when: (1) predictions must react to events within seconds-minutes (fraud, anomaly detection), (2) features depend on real-time aggregations (session behavior, trending topics), (3) downstream systems are event-driven (notifications, alerts). Synchronous REST is preferred when: (1) sub-second response to user is needed (search, chatbot), (2) request-response pattern fits naturally, (3) system is simple and doesn\'t need event replay. Many systems use both: streaming for feature computation, REST for serving', 'Streaming is always superior to synchronous inference', 'Streaming architecture requires specialized ML frameworks'], correctAnswer: 1, explanation: 'Trade-offs: Streaming (Kafka→Flink→model→Kafka): natural backpressure handling, event replay for debugging, decoupled components. But: adds 10-100ms latency for message passing, more infrastructure complexity, eventual consistency. Synchronous (REST API): simple request-response, sub-10ms added latency, easy to debug. But: no replay, tight coupling, backpressure via rate limiting only. Hybrid pattern: Kafka for feature aggregation + event triggering, REST for real-time serving. Example: fraud detection uses Kafka for real-time feature computation (transaction velocity) and REST API for synchronous scoring.', tags: ['streaming', 'kafka', 'rest', 'event-driven'] },
  { id: 'ai-engineer-ai-system-design-l4-008', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'A/B Testing', question: 'What is the variance reduction technique CUPED for ML A/B tests?', options: ['CUPED (Controlled-experiment Using Pre-Experiment Data) reduces the variance of A/B test metrics by regressing out pre-experiment behavior. If a user\'s metric is correlated with their pre-experiment value (likely for engagement, revenue), CUPED adjusts: Y_adj = Y - θ·X_pre, where θ minimizes variance. This can reduce required sample size by 50%+ by removing user-level baseline variation, enabling faster and more sensitive ML model experiments', 'CUPED increases the sample size needed for A/B tests', 'CUPED is a data compression technique', 'CUPED only works for binary outcome metrics'], correctAnswer: 0, explanation: 'In ML A/B tests, user-level metrics (revenue, engagement) have high variance from individual differences. CUPED exploits the correlation between pre-experiment and during-experiment behavior: a high-spending user will likely spend high in both control and treatment. By subtracting the predicted contribution from pre-experiment behavior (Y_adj = Y_post - θ·Y_pre), the remaining variance is due to the treatment effect. θ = Cov(Y_post, Y_pre) / Var(Y_pre). Netflix and Uber report 50-80% variance reduction, enabling 2-4x faster experiment completion.', tags: ['cuped', 'ab-testing', 'variance-reduction', 'experimentation'] },
  { id: 'ai-engineer-ai-system-design-l4-009', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'RAG System', question: 'How should document access control be implemented in a multi-user RAG system?', options: ['All users should have access to all documents in a RAG system', 'RAG systems do not need access control', 'Access control in RAG requires: (1) per-document ACLs stored as metadata in the vector database, (2) filtering during retrieval to only return documents the user has access to, (3) handling group/role-based permissions (user inherits group access), (4) real-time permission updates (when access is revoked, the document should immediately become unretrievable). The filtering must happen at the vector DB query level, not post-retrieval, to prevent information leakage through embedding similarity', 'Post-retrieval filtering is sufficient for access control'], correctAnswer: 2, explanation: 'Security concern: if filtering happens after retrieval, the LLM might have already seen the document content via the embedding search results (the chunk text is returned). Access control must be enforced during the vector search itself. Implementation: (1) store user_id/group_ids as metadata on each vector, (2) add metadata filter to every query: filter={user_id: current_user OR group_id IN user_groups}, (3) for real-time permission changes: update metadata in vector DB when permissions change. Challenges: complex permission hierarchies (user → group → org), performance impact of filtering (pre-filter vs post-filter trade-offs), and audit logging for compliance.', tags: ['rag', 'access-control', 'security', 'multi-user'] },
  { id: 'ai-engineer-ai-system-design-l4-010', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Model Serving', question: 'What is disaggregated serving and why is it optimal for LLM inference?', options: ['Disaggregated serving doubles inference latency', 'Disaggregated serving separates prefill (processing the input prompt) and decode (generating tokens) onto different hardware. Prefill is compute-bound (benefits from high-FLOPS GPUs), while decode is memory-bandwidth-bound (benefits from high-bandwidth memory). By routing each phase to optimized hardware, overall throughput increases 2-3x compared to running both on the same GPUs. The KV cache is transferred between prefill and decode nodes', 'Prefill and decode have identical hardware requirements', 'All LLM inference should run on a single GPU type'], correctAnswer: 1, explanation: 'Prefill: process N tokens → N parallel matmuls. Arithmetic intensity ∝ N (compute-bound for large prompts). Best on: high-compute GPUs (H100 SXM). Decode: generate 1 token → load all weights for 1 matmul. Arithmetic intensity ∝ 1 (memory-bound). Best on: high-bandwidth memory or many cheaper GPUs. DistServe (Zhong et al. 2024): separate prefill and decode clusters. Prefill nodes produce KV caches → transfer to decode nodes via high-speed interconnect. Result: each hardware type runs at peak efficiency. Splitwise (Microsoft) takes this further with the split between prompt processing and token generation.', tags: ['disaggregated-serving', 'prefill', 'decode', 'hardware-optimization'] },
  { id: 'ai-engineer-ai-system-design-l4-011', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Resilience', question: 'What fallback strategies should ML systems implement for graceful degradation?', options: ['ML systems should return errors when the model is unavailable', 'Graceful degradation strategies: (1) model cascade: fall back to simpler/faster model when primary is unavailable, (2) cached predictions: serve last-known-good predictions for frequently requested items, (3) rule-based fallback: hand-crafted rules that provide reasonable defaults, (4) feature degradation: serve with fewer features if some feature sources fail. Each fallback should be tested regularly and have clear trigger conditions. Users should receive lower-quality results rather than no results', 'Only the primary model needs to be tested', 'Graceful degradation always provides the same quality as the primary model'], correctAnswer: 1, explanation: 'Fallback hierarchy example for recommendations: (1) Primary: personalized ML model (best quality), (2) Fallback 1: popular items for user segment (when user features unavailable), (3) Fallback 2: globally popular items (when ML service is down), (4) Fallback 3: curated editorial list (when all systems fail). Each level provides progressively simpler but still useful results. Circuit breaker pattern: when primary model error rate > 10% for 30 seconds, automatically switch to Fallback 1. Alert on-call. Auto-recovery: when primary model health recovers, gradually shift traffic back (5% → 25% → 50% → 100%).', tags: ['graceful-degradation', 'fallback', 'resilience', 'circuit-breaker'] },
  { id: 'ai-engineer-ai-system-design-l4-012', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Cost', question: 'How should ML inference costs be attributed in a multi-team organization?', options: ['ML infrastructure costs are too small to warrant attribution', 'Cost attribution requires: (1) per-request tagging with team/product/tenant identifiers, (2) GPU-time tracking per model variant, (3) token counting for LLM APIs, (4) showback/chargeback dashboards showing each team\'s ML infrastructure usage. This creates accountability — teams optimize their models and request patterns when they see costs. Infrastructure: request tracing propagates cost tags through the serving stack, GPU utilization is attributed to model instances, and aggregated billing reports are generated per cost center', 'Only training costs need attribution, not inference costs', 'ML costs should be paid by a central platform team'], correctAnswer: 1, explanation: 'Without attribution: ML platform costs grow unchecked because no team feels responsible. With attribution: team A sees their poorly optimized model costs $50K/month → motivates quantization (saves 3x) or caching (saves 2x). Implementation: (1) each API request includes team_id header, (2) serving framework logs (team_id, model, gpu_ms, tokens) per request, (3) billing pipeline aggregates logs into per-team costs, (4) dashboards show: cost per team, cost per model, cost per query. Governance: set budgets per team, alert on budget thresholds, require cost justification for new model deployments. Companies like Uber, Netflix attribute ML costs to product teams to drive efficiency.', tags: ['cost-attribution', 'chargeback', 'infrastructure', 'optimization'] },
  { id: 'ai-engineer-ai-system-design-l4-013', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Search', question: 'How does a modern AI-powered search system combine multiple retrieval signals?', options: ['AI search only needs a single vector retrieval', 'A single retrieval stage is sufficient for production search', 'Modern search combines: (1) sparse retrieval (BM25 for exact keyword matching), (2) dense retrieval (embedding similarity for semantic matching), (3) knowledge graph traversal (entity relationships), (4) personalization signals (user history, preferences). Results are merged via reciprocal rank fusion or a learned ranker. A cross-encoder reranker provides the final ranking. The system serves this multi-stage pipeline within a latency budget of 100-200ms', 'Keyword search is no longer needed with vector retrieval'], correctAnswer: 2, explanation: 'Example: query "Python list comprehension performance." BM25 finds docs with exact terms. Dense retrieval finds docs about "Python list operations speed" (semantic match). Knowledge graph links "list comprehension" → "generator expression" → related docs. Personalization boosts results matching user\'s skill level. Fusion: RRF(doc) = Σ 1/(60 + rank_i(doc)) across all retrievers. Reranking: cross-encoder scores top-100 candidates for final ordering. Architecture: parallel retrieval (BM25 + dense + KG in parallel, ~50ms) → fusion (~5ms) → reranking (~100ms) = ~155ms total. Each retriever catches cases others miss.', tags: ['search', 'hybrid-retrieval', 'rrf', 'reranking'] },
  { id: 'ai-engineer-ai-system-design-l4-014', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Capacity', question: 'How should GPU capacity be planned for LLM serving workloads?', options: ['Static provisioning without autoscaling is always sufficient', 'GPU memory is never a bottleneck for LLM serving', 'LLM capacity planning must model: (1) KV cache memory per concurrent request (limits max concurrency per GPU), (2) prefill throughput (tokens/sec determines prompt processing capacity), (3) decode throughput (tokens/sec/request determines generation speed), (4) target latency SLA (constrains batch size). For a 7B model in FP16 on A100-80GB: ~14GB model + ~500KB KV per 2K-context request → ~130 concurrent requests max. Real capacity is lower due to compute bottleneck during decode', 'GPU capacity planning is the same as CPU planning'], correctAnswer: 2, explanation: 'Capacity planning example: 7B model, 100 req/s, avg 500 input + 200 output tokens, p99 TTFT < 500ms, p99 total < 5s. Per GPU (A100-80GB): model 14GB, remaining 66GB for KV cache. KV per request (32 layers, 32 heads, 128d, FP16): ~500KB for 2K tokens → 66GB/500KB = ~130K max positions, but compute limits to ~50 concurrent decodes at 25 tokens/s. Throughput: 50 concurrent × 25 tok/s = 1250 output tok/s, or ~6 req/s at 200 tokens each. Need: 100/6 ≈ 17 A100 GPUs + 30% headroom = 22 GPUs.', tags: ['capacity-planning', 'gpu-memory', 'kv-cache', 'throughput'] },
  { id: 'ai-engineer-ai-system-design-l4-015', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Feedback', question: 'How do feedback loops in ML systems cause model degradation over time?', options: ['Feedback loops can be completely prevented by model design', 'Feedback loops always improve model accuracy', 'Feedback loops only occur in recommendation systems', 'Feedback loops degrade models when: (1) the model\'s predictions influence future training data (a spam filter that blocks spam reduces the proportion of spam in training data → model forgets to detect spam), (2) user behavior adapts to model outputs (recommendation model shows X → users click X → model learns X is popular → more X shown — filter bubble), (3) adversaries adapt (fraud model catches pattern A → fraudsters switch to pattern B → model fails). Breaking loops requires: exploration, counterfactual evaluation, and regular retraining on diverse data including synthetic/historical examples'], correctAnswer: 3, explanation: 'Types: (1) Direct loop: model output becomes training label (auto-labeling systems), (2) Indirect loop: model output changes environment which changes input distribution (dynamic pricing → buyer behavior changes), (3) Bandit loop: model decides what data it sees (exploration-exploitation). Examples: credit scoring model denies loans to a demographic → no outcome data for that group → model becomes more discriminatory. Solutions: (a) randomized exploration (show some non-optimal recommendations to gather diverse data), (b) counterfactual evaluation (estimate what would have happened under different decisions), (c) importance sampling (weight training data to correct for selection bias).', tags: ['feedback-loops', 'model-degradation', 'filter-bubble', 'distribution-shift'] },
  { id: 'ai-engineer-ai-system-design-l4-016', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'API Design', question: 'What is the optimal API design for an LLM inference service supporting both sync and async workloads?', options: ['A single synchronous endpoint handles all workloads', 'Streaming should use WebSockets instead of SSE', 'Best practice: (1) POST /v1/chat/completions — synchronous, stream=false for quick responses, (2) POST /v1/chat/completions?stream=true — SSE streaming for real-time token delivery, (3) POST /v1/batch — async batch endpoint returning job_id, polled via GET /v1/batch/{job_id}. Include in responses: model version, token counts (prompt/completion), finish reason (stop/length/content_filter), and request_id for tracing. Implement idempotency keys for retry safety and rate limiting per API key', 'Batch and real-time should share the same processing pipeline'], correctAnswer: 2, explanation: 'OpenAI-compatible API design has become a de facto standard. Key design choices: (1) SSE over WebSocket for streaming: simpler, HTTP-based, naturally supports proxies and CDNs, auto-reconnects. (2) Separate batch endpoint: queue-based processing with higher throughput and lower cost, clients poll for results. (3) Usage tracking: response includes prompt_tokens and completion_tokens for billing. (4) Content filtering: finish_reason="content_filter" when safety systems intervene. (5) Function calling: structured tool_calls in response. Versioning: /v1/ prefix enables breaking changes in /v2/ without disruption. Rate limiting: token bucket per API key with separate limits for different endpoints.', tags: ['api-design', 'streaming', 'batch', 'openai-compatible'] },
  { id: 'ai-engineer-ai-system-design-l4-017', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Guardrails', question: 'How should safety guardrails be architecturally integrated without becoming a latency bottleneck?', options: ['Safety analysis should only happen on model outputs', 'Guardrails should be embedded directly in the model', 'All safety checks must complete before generation starts', 'Async safety architecture: (1) fast blocklist/regex check on input (<1ms, synchronous), (2) start LLM generation immediately, (3) run input safety classifier in parallel with generation, (4) if input classifier flags: cancel generation and return refusal, (5) stream output through lightweight output filter (check each chunk for PII/toxicity). Heavy safety analysis (factual verification, policy compliance) runs asynchronously post-response and triggers alerts for human review rather than blocking the response'], correctAnswer: 3, explanation: 'Latency impact of sequential safety: input check (100ms) + generation (2000ms) + output check (100ms) = 2200ms. Parallel approach: fast input screen (1ms) + generation starts immediately + parallel deep input check (100ms, kills generation if triggered) + streaming output filter (adds 0ms per chunk, 10ms for PII regex). Total: ~2010ms (saving 190ms). For output safety: stream each token through a lightweight filter; run a comprehensive safety analysis on the complete response asynchronously. If the async check finds issues, the response is flagged for review and the user is notified. This provides defense-in-depth without serializing all checks.', tags: ['guardrails', 'latency', 'parallel-safety', 'streaming'] },
  { id: 'ai-engineer-ai-system-design-l4-018', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Multi-Region', question: 'How should a global LLM application handle data residency requirements across regions?', options: ['Data residency architecture: (1) deploy separate LLM serving instances per region (EU, US, APAC), (2) route requests by user geography to regional endpoints, (3) keep user data (conversations, documents) in regional storage, (4) use a global model but regional KV cache and logging. RAG: document indices must be regional (EU user queries only search EU-stored documents). Challenges: model consistency across regions (same version), feature parity, and handling users who travel across regions', 'GDPR does not apply to AI inference data', 'Data residency only applies to training data', 'All data can be processed in a single region'], correctAnswer: 0, explanation: 'GDPR requires EU resident data to be processed in the EU (or adequate countries). Architecture: (1) DNS/CDN routes EU users to EU endpoints, (2) EU conversation data stored in EU-region databases, (3) EU RAG index contains only EU-authorized documents, (4) Model weights (no personal data) can be globally distributed. Complications: (a) fine-tuning: EU user feedback cannot leave the EU for centralized training → federated fine-tuning or EU-only training jobs, (b) monitoring: EU logs analyzed in-region, (c) model updates: trained centrally on anonymized data, deployed globally. US health data (HIPAA): similar constraints for PHI. The system must tag data with jurisdiction and enforce routing rules throughout the pipeline.', tags: ['data-residency', 'gdpr', 'multi-region', 'compliance'] },
  { id: 'ai-engineer-ai-system-design-l4-019', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Ensemble', question: 'What is the model cascade pattern and when does it outperform a single model?', options: ['The small model in a cascade must be retrained whenever the large model changes', 'A single large model is always better than a cascade', 'Model cascade: route easy queries to a small/cheap model; only escalate to a large/expensive model when the small model is uncertain. Detection: if small model confidence < threshold, escalate. This achieves near-large-model quality at near-small-model cost because 70-80% of queries are easy enough for the small model. The key is a well-calibrated confidence measure — miscalibrated confidence wastes money (under-confident) or degrades quality (over-confident)', 'Model cascades always have higher latency than single models'], correctAnswer: 2, explanation: 'Example: GPT-4o-mini as small model ($0.15/1M tokens), GPT-4o as large model ($2.50/1M tokens). If 75% of queries go to mini and 25% escalate: cost = 0.75×$0.15 + 0.25×$2.50 = $0.74/1M tokens (70% savings vs all GPT-4o, <5% quality loss). Confidence estimation: (a) output probability entropy (low entropy = confident), (b) self-assessment ("Rate your confidence 1-10"), (c) consistency across samples (generate 3 responses — if they agree, confident). Production: FrugalGPT (Chen et al. 2023) demonstrated this approach, and LLM routing is now standard practice at companies optimizing API costs.', tags: ['model-cascade', 'cost-optimization', 'confidence', 'routing'] },
  { id: 'ai-engineer-ai-system-design-l4-020', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Graph ML', question: 'What are the system challenges unique to serving Graph Neural Network (GNN) predictions?', options: ['GNN serving challenges: (1) neighbor sampling: each prediction requires fetching multi-hop neighbors from the graph — 2-hop on a node with degree 1000 means reading 1M neighbor features, (2) the graph must be stored and accessible at serving time (graph DB or in-memory), (3) graph updates (new edges/nodes) must propagate to inference without full recomputation, (4) feature aggregation is variable-time depending on node degree. Solutions: pre-computed embeddings (distill GNN into MLP for serving), mini-batch neighbor sampling with degree caps, and graph caching layers', 'GNN serving is identical to standard model serving', 'GNNs do not need graph access at inference time', 'All GNN nodes require identical computation time'], correctAnswer: 0, explanation: 'Standard MLP/transformer: input → fixed computation → output. GNN: input node → fetch 1-hop neighbors → fetch their features → aggregate → fetch 2-hop → aggregate → predict. For a social network node with 5000 friends, each with 5000 friends: 2-hop neighborhood = potentially 25M nodes to read. Solutions: (1) Neighbor sampling: randomly sample 15 neighbors per hop → read ~225 nodes max, (2) Pre-compute: run GNN offline, store node embeddings, serve via embedding lookup (O(1) inference, but stale), (3) Distillation: train an MLP to mimic the GNN\'s outputs — MLP takes node features only (no graph needed at inference). Pinterest uses this approach for their recommendation GNN.', tags: ['gnn-serving', 'graph-database', 'neighbor-sampling', 'distillation'] },
  { id: 'ai-engineer-ai-system-design-l4-021', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Testing', question: 'What is shadow mode (dark launch) and how does it de-risk ML model deployments?', options: ['Shadow mode requires double the infrastructure permanently', 'Shadow mode means running models without electricity', 'Shadow mode runs the new model alongside production, processing the same live traffic, but only the production model\'s predictions are served. The shadow model\'s outputs are logged for comparison. This de-risks deployment by: (1) validating on real traffic patterns (not just test sets), (2) catching latency issues under production load, (3) comparing prediction distributions between old and new models, (4) identifying edge cases in production data that test sets miss. Only after shadow metrics pass thresholds is the new model promoted to production', 'Shadow mode is unnecessary for well-tested models'], correctAnswer: 2, explanation: 'Shadow deployment workflow: (1) deploy new model v2 alongside v1, (2) route all requests to both (or sample 100%), (3) serve only v1 responses to users, (4) log v2 predictions for comparison, (5) analyze: prediction agreement rate, latency comparison, error rates, distribution differences. Duration: typically 1-7 days depending on traffic volume. Promotion criteria: (a) v2 prediction quality ≥ v1 on sampled ground truth, (b) v2 latency p99 ≤ v1 + 10%, (c) no novel error patterns, (d) prediction distribution is reasonable. Cost: temporary 2x compute (only during shadow period). Risk: near-zero (users never see v2 predictions). Used by Google, Netflix, Uber for major model launches.', tags: ['shadow-mode', 'dark-launch', 'deployment', 'de-risking'] },
  { id: 'ai-engineer-ai-system-design-l4-022', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Edge', question: 'What are the trade-offs between on-device ML and cloud ML for mobile applications?', options: ['On-device: (1) zero network latency, (2) works offline, (3) user data stays on device (privacy), (4) no per-request API cost. But: limited by device compute/memory (model <100MB), harder to update (app store release cycle), limited model capability. Cloud: (1) unlimited model size and compute, (2) easy model updates (server-side), (3) can use the latest models. But: requires network, adds latency, ongoing API costs, privacy concerns. Hybrid: on-device for simple/latency-critical tasks, cloud for complex/accuracy-critical tasks', 'Privacy is not a benefit of on-device ML', 'On-device ML has no limitations compared to cloud', 'Cloud ML is always superior to on-device ML'], correctAnswer: 0, explanation: 'Decision framework: On-device when: latency-critical (keyboard prediction <10ms), offline essential (image recognition in areas without connectivity), privacy-required (health data), high-frequency (predictions every keystroke — cost-prohibitive in cloud). Cloud when: accuracy-critical (medical diagnosis — need large model), rapidly evolving (model updated daily), complex (multi-modal, large context). Hybrid examples: (1) voice assistant: on-device wake word detection → cloud for full speech recognition, (2) photo app: on-device face detection → cloud for complex editing suggestions, (3) search: on-device autocomplete → cloud for full search results.', tags: ['on-device', 'edge-ml', 'cloud-ml', 'mobile'] },
  { id: 'ai-engineer-ai-system-design-l4-023', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Embedding', question: 'How should a high-throughput embedding service be designed for production use?', options: ['Embedding computation is too fast to benefit from batching', 'Embedding services should use CPU instead of GPU', 'High-throughput embedding service design: (1) request batching (accumulate requests for 5-10ms or until batch is full → process as single GPU batch for 10x throughput), (2) model optimization (ONNX/TensorRT for 2-4x speedup), (3) dynamic batching with priority queues (latency-sensitive requests skip the batch queue), (4) horizontal scaling (stateless service behind load balancer), (5) result caching (hash text → cached embedding, ~30-50% hit rate for repeated content). Throughput target: 10K+ embeddings/second on a single A10G GPU', 'Each embedding request should be processed individually'], correctAnswer: 2, explanation: 'Without batching: 1 text → tokenize → GPU forward pass → embedding. GPU utilization: ~5% (most time waiting for data transfer). With batching: 32 texts → tokenize → GPU forward pass → 32 embeddings. GPU utilization: ~80% (GPU compute dominates). Throughput: 32x more embeddings per second. Implementation: async request queue with max_wait_time=10ms and max_batch_size=64. Optimization stack: model in ONNX format → ONNX Runtime with TensorRT execution provider → FP16 inference. Caching: hash(text) → embedding in Redis, TTL 24h. For 768-d float32 embeddings: 3KB each, 1M cached = 3GB Redis. A single A10G can serve 10K+ embeddings/second with batching + optimization.', tags: ['embedding-service', 'batching', 'throughput', 'optimization'] },
  { id: 'ai-engineer-ai-system-design-l4-024', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Monitoring', question: 'How should ML system monitoring be layered for effective alerting?', options: ['Only infrastructure metrics need monitoring for ML systems', 'A single dashboard is sufficient for ML monitoring', 'ML model metrics cannot be monitored in real-time', 'Layered monitoring: (1) Business metrics (revenue, conversion — top-level health), (2) Model metrics (accuracy, drift, calibration — ML-specific health), (3) Service metrics (latency, throughput, error rate — serving health), (4) Infrastructure metrics (GPU util, memory, disk — resource health). Alerts should cascade: infra alert → investigate service → check model → verify business impact. Avoid alert fatigue by: alerting on symptoms not causes, using composite alerts, and setting actionable thresholds based on business impact rather than statistical significance'], correctAnswer: 3, explanation: 'Monitoring cascade example: GPU memory at 95% (infra) → increased latency (service) → model serving timeouts → prediction errors → revenue drop (business). Without layered monitoring, you only see the revenue drop and must investigate all layers. With layered monitoring: alert on GPU memory at 85% (infra) → investigate before it affects service. Key metrics per layer: Business: revenue per decision, user satisfaction. Model: prediction drift (PSI), feature drift, accuracy on delayed labels. Service: p50/p99 latency, requests/sec, error rate, queue depth. Infra: GPU utilization, memory, GPU temperature, network I/O. Tools: Grafana for infra+service, Evidently/Whylabs for model, custom dashboards for business. PagerDuty/OpsGenie for alerting with escalation policies.', tags: ['monitoring', 'layered', 'alerting', 'observability'] },
  { id: 'ai-engineer-ai-system-design-l4-025', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Data Pipeline', question: 'What is the medallion architecture for ML data pipelines?', options: ['The medallion architecture only works with streaming data', 'All data should be stored in a single layer', 'Bronze-Silver-Gold layers: Bronze stores raw ingested data (append-only, schema-on-read). Silver contains cleaned, validated, deduplicated data with enforced schemas. Gold has aggregated, feature-engineered data ready for ML. Benefits: raw data preserved for debugging, cleaning logic centralized in bronze→silver, multiple ML teams build different gold tables from shared silver data. Implemented on Delta Lake, Apache Iceberg, or Apache Hudi atop object storage', 'The medallion architecture is a model training approach'], correctAnswer: 2, explanation: 'Example ML pipeline: Bronze: raw Kafka events (JSON, varying schemas, duplicates) → Silver: parsed events with enforced schema, deduplicated, PII masked, valid ranges checked → Gold (for fraud model): 30-day transaction aggregates, velocity features, merchant risk scores. Gold (for recommendation model): user preference vectors, item popularity scores, session sequences. Multiple Gold tables from the same Silver data enable different ML teams to work independently while sharing data quality guarantees. Data quality gates between layers (Great Expectations) catch issues before they reach model training.', tags: ['medallion', 'data-pipeline', 'delta-lake', 'data-quality'] },
  { id: 'ai-engineer-ai-system-design-l4-026', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Model Router', question: 'What is an intelligent model router and how does it optimize cost-quality trade-offs?', options: ['An intelligent router classifies incoming queries by difficulty/type and routes to the optimal model: simple factual queries → small model (cheap, fast), complex reasoning → large model (expensive, accurate), code → code-specialized model, creative writing → creative model. The router can be: a lightweight classifier, embedding similarity to difficulty-labeled examples, or the small model\'s own confidence. This achieves 90-95% of large model quality at 20-30% of the cost', 'Routing decisions should be made by the user, not the system', 'Model routing always degrades quality proportionally to cost savings', 'Always use the most capable model for best results'], correctAnswer: 0, explanation: 'Implementation: train a BERT classifier on (query_text, optimal_model) labels derived from: run all queries through all models, label each query with the cheapest model that produces satisfactory quality. At inference: classify query (2ms) → route to selected model. Alternatively: always try small model first → if response quality score < threshold (evaluated by a lightweight judge) → re-route to large model. Martian, Unify, and OpenRouter implement commercial model routing. Cost savings: if 70% of queries go to a 10x cheaper model, average cost = 0.7×1 + 0.3×10 = 3.7x instead of 10x (63% savings). Quality impact: the router\'s accuracy determines the gap — a 95%-accurate router loses <2% quality.', tags: ['model-router', 'cost-quality', 'intelligent-routing', 'optimization'] },
  { id: 'ai-engineer-ai-system-design-l4-027', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Blue-Green', question: 'How does blue-green deployment work for ML models with warm-up requirements?', options: ['Warm-up is unnecessary for GPU-based models', 'ML model blue-green deployment: (1) provision green environment and load new model (model loading takes 2-30 minutes for large models on GPU), (2) warm up the model with synthetic traffic (fill caches, compile kernels with torch.compile), (3) run smoke tests on green, (4) switch traffic atomically from blue to green, (5) keep blue running for 15-30 minutes for quick rollback if issues arise, (6) decommission blue. The warm-up phase is critical — cold models have 2-5x higher latency on first requests due to CUDA kernel compilation and cache misses', 'ML models can be swapped instantly like web services', 'Blue-green deployment requires zero downtime preparation'], correctAnswer: 1, explanation: 'LLM warm-up sequence: (1) Load model weights to GPU (7B model: ~30s from disk, 2-5min from S3), (2) torch.compile optimization (first forward pass triggers kernel compilation: 30-120s), (3) CUDA cache warmup (run 10-50 representative requests to fill KV cache page pool, cuBLAS handle initialization), (4) Health check passes. Without warmup: first requests see 3-10x normal latency, potentially causing timeouts and SLA violations. Automation: Kubernetes readiness probe only passes after warmup completes. Traffic switch: update load balancer/ingress to point to green. Rollback: switch back to blue (still warm and running) within seconds.', tags: ['blue-green', 'warm-up', 'deployment', 'gpu-initialization'] },
  { id: 'ai-engineer-ai-system-design-l4-028', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Microservice', question: 'When should ML functionality be a separate microservice versus embedded in the application?', options: ['Separate service when: (1) the model needs GPU and the app doesn\'t (different scaling), (2) multiple applications use the same model (shared service), (3) the model has different release cadence than the app, (4) the model team is separate from the app team. Embed when: (1) latency is critical (avoid network hop), (2) the model is small (ONNX on CPU), (3) the system is simple (one team, one app). Separate services add 5-20ms network latency and operational complexity but enable independent scaling and deployment', 'The decision has no impact on system performance', 'ML should always be embedded in the application', 'ML should always be a separate microservice'], correctAnswer: 0, explanation: 'Decision matrix: Single app + small model + one team → embed (sidecar pattern or in-process). Multiple apps + shared model → separate service (avoid duplication, single model version). GPU model + CPU app → separate service (different hardware needs). Rapid model iteration → separate service (deploy model without redeploying app). Ultra-low latency (<5ms) → embed (avoid network hop). Common pattern: model-as-a-service with gRPC for internal ML, REST gateway for external clients. Scaling: app scales on CPU based on traffic, model service scales on GPU based on inference load — independent scaling is a major advantage of separation.', tags: ['microservice', 'architecture', 'separation', 'scaling'] },
  { id: 'ai-engineer-ai-system-design-l4-029', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Evaluation Infra', question: 'How should an evaluation infrastructure be designed for continuous ML model assessment?', options: ['Evaluation only needs to run during model development', 'Continuous evaluation infrastructure: (1) evaluation dataset management (versioned test sets, slice definitions), (2) automated evaluation pipeline triggered on model changes, (3) metric computation across multiple dimensions (overall, per-slice, per-feature), (4) regression detection (is the new model worse on any slice?), (5) report generation with statistical significance tests, (6) integration with model registry (block promotion if evaluation fails). For LLMs: add LLM-as-Judge evaluation, behavioral testing, and safety benchmarks alongside accuracy metrics', 'A single test set is sufficient for all evaluations', 'Evaluation infrastructure is not needed for production systems'], correctAnswer: 1, explanation: 'Production evaluation infra: (1) Dataset store: versioned, with metadata (creation date, source, slice labels). (2) Eval runner: takes (model_version, dataset_version, metric_suite) → computes all metrics → stores in metrics DB. (3) Comparison engine: new model vs champion, with paired t-tests and confidence intervals per slice. (4) Gate: if any critical slice regresses by >X%, block deployment. (5) Dashboard: historical metric trends, slice-level drill-down, automated reports for stakeholders. Trigger: (a) on every model push to registry, (b) on schedule (weekly) with latest production data, (c) on data distribution change detection. For LLMs: automated eval suites (MMLU, HumanEval, safety benchmarks) plus domain-specific evaluations run automatically.', tags: ['evaluation-infra', 'continuous-evaluation', 'regression-testing', 'metrics'] },
  { id: 'ai-engineer-ai-system-design-l4-030', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Real-Time Features', question: 'How should real-time features (computed from streaming events) be integrated into ML serving?', options: ['Batch features are always sufficient for ML serving', 'Real-time features should be computed synchronously in the API request handler', 'Real-time features are computed during model inference', 'Real-time feature architecture: (1) events stream through Kafka → Flink/Spark Streaming computes features (e.g., transaction count in last 5 minutes), (2) computed features are written to a low-latency online store (Redis, DynamoDB), (3) at inference time, the serving layer reads features from the online store and passes them to the model. Challenges: exactly-once semantics (avoid double-counting), late-arriving events, and feature consistency between training (batch-computed) and serving (stream-computed)'], correctAnswer: 3, explanation: 'Example: fraud detection. Events: card transactions arrive via Kafka. Real-time features needed: (1) transaction_count_5min for this card, (2) total_amount_1hour, (3) distinct_merchants_24h. Flink job maintains windowed aggregations, writes to Redis: key=card_id, values={tx_count_5min: 3, total_1h: $450, merchants_24h: 7}. Inference: API receives transaction → read card features from Redis (~1ms) + read user features from online store (~2ms) → model prediction (~5ms) → total ~8ms. Training: the same features must be computed from batch data with identical logic (use the same Flink code for both stream and batch, or verify equivalence). Feature freshness: Redis values updated within seconds of events.', tags: ['real-time-features', 'streaming', 'flink', 'online-store'] },
  { id: 'ai-engineer-ai-system-design-l4-031', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Batch Architecture', question: 'How should large-scale batch ML inference be architected for cost efficiency?', options: ['Batch inference has the same cost per prediction as real-time', 'Batch inference optimization: (1) use spot/preemptible instances (60-90% cheaper), with checkpointing for fault tolerance, (2) maximize batch size to fully utilize GPU compute, (3) sort inputs by length to minimize padding waste, (4) use data parallelism across multiple GPUs, (5) pipeline data loading and inference (prefetch next batch while current batch processes), (6) write results to a distributed store (S3/GCS) with exactly-once semantics. Batch inference can achieve 5-20x better cost-per-prediction than real-time serving by maximizing GPU utilization', 'Batch inference should use the same infrastructure as real-time serving', 'Batch inference cannot use spot instances due to preemption risk'], correctAnswer: 1, explanation: 'Real-time serving: GPU idle between requests, small batches, provisioned for peak traffic → ~20-40% average GPU utilization. Batch inference: process all inputs back-to-back, large batches, run exactly as long as needed → ~80-95% GPU utilization. Cost example: 1M embeddings. Real-time: 4 A10G always-on @ $1/hr × 24h = $96/day, processing 1M in ~2 hours of actual work. Batch: 4 A10G spot @ $0.30/hr × 2h = $2.40. That\'s 40x cheaper. Architecture: job queue (SQS/Redis) → worker pool (auto-scaling GPU instances) → process batches → write to S3 → completion callback. Checkpointing: save progress every 1000 items, resume from checkpoint after spot preemption.', tags: ['batch-inference', 'spot-instances', 'cost-efficiency', 'gpu-utilization'] },
  { id: 'ai-engineer-ai-system-design-l4-032', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Data Mesh', question: 'How does the data mesh paradigm affect ML feature engineering and model development?', options: ['In a data mesh, domain teams own their data as products with quality SLAs. ML impact: (1) feature engineering uses domain data products via standardized interfaces rather than reaching into raw databases, (2) data contracts between domains prevent silent schema changes that break ML pipelines, (3) domain-specific ML models can be built by domain teams on their data products, (4) cross-domain models must negotiate access through data product APIs. This distributes both data ownership and ML responsibility, but requires strong governance for consistency', 'ML teams should bypass data products and access raw data directly', 'Data mesh eliminates the need for feature stores', 'Data mesh centralizes all data for ML consumption'], correctAnswer: 0, explanation: 'Traditional: central data team builds warehouse → ML team queries it. Data mesh: each domain (payments, user-profile, content) publishes data products with SLAs (freshness, quality, schema). ML team consumes data products. Benefits: (a) data quality enforced at source (payments team guarantees transaction data quality), (b) schema changes communicated via data contracts → no surprise breakages, (c) domain expertise embedded in data products (payments team knows how to handle chargebacks). Challenges: cross-domain features (user × payment × content) require combining multiple data products → need a feature store or orchestration layer that joins data products while respecting each domain\'s SLAs and access policies.', tags: ['data-mesh', 'feature-engineering', 'data-products', 'governance'] },
  { id: 'ai-engineer-ai-system-design-l4-033', language: 'ai-engineer', level: 'level4', category: 'AI System Design', subcategory: 'Disaster Recovery', question: 'What is the recovery time objective (RTO) and recovery point objective (RPO) for ML systems?', options: ['ML systems do not need disaster recovery objectives', 'ML systems only need backup for model weights, not predictions or data', 'RTO defines how quickly the ML service must be restored after failure. RPO defines how much data (predictions, feedback, model state) can be lost. For real-time ML serving: RTO should be minutes (automatic failover to standby model server), RPO near-zero (no predictions lost). For training: RTO can be hours (restart from checkpoint), RPO depends on checkpoint frequency. Key: model artifacts stored in multiple regions, serving instances across availability zones, and automatic health check + failover mechanisms', 'RTO and RPO are the same metric'], correctAnswer: 2, explanation: 'ML-specific DR considerations: (1) Model serving: active-active across 2+ AZs, automatic failover if one AZ fails. RTO: 0 (traffic automatically routes to healthy AZ). (2) Model artifacts: stored in multi-region object storage (S3 with cross-region replication). RPO: 0 (always available). (3) Training: checkpointing every N minutes. If training server fails: restart from last checkpoint. RPO: N minutes of training progress. (4) Feature store: online store replicated across AZs. (5) Prediction logging: async write to durable store, small buffer may be lost during sudden failure. (6) RAG index: maintain replica in secondary region, switch if primary fails. DR testing: quarterly chaos engineering exercises (kill a serving node, simulate AZ failure) to verify RTO/RPO targets are met.', tags: ['disaster-recovery', 'rto', 'rpo', 'high-availability'] },
];

export default questions;
